pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress.code.length > 0);
        // Record balances of recipients before the call
        uint256[] memory beforeBal = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            beforeBal[i] = _tos[i].balance;
        }
        // Call transfer
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = true;
            // The reference contract returns true; for the buggy version it returns false
            // We don't care about return value, only the balance effect
        } catch {
            success = false;
        }
        if (success) {
            // If the transfer succeeded, each recipient must have gained exactly v
            for (uint i = 0; i < _tos.length; i++) {
                assertTrue(_tos[i].balance == beforeBal[i] + v);
            }
        }
    }
}

